import math


def analyze_timings(timings):
    keys = ["namelookup", "connect", "appconnect", "starttransfer", "total"]
    if not isinstance(timings, dict):
        raise ValueError("invalid timings")

    values = []
    for key in keys:
        value = timings.get(key)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("invalid timings")
        if not math.isfinite(value) or value < 0:
            raise ValueError("invalid timings")
        values.append(float(value))

    for left, right in zip(values, values[1:]):
        if right < left:
            raise ValueError("invalid timings")

    namelookup, connect, appconnect, starttransfer, total = values
    result = {
        "dns": round(namelookup * 1000, 1),
        "tcp": round((connect - namelookup) * 1000, 1),
        "tls": round((appconnect - connect) * 1000, 1),
        "server": round((starttransfer - appconnect) * 1000, 1),
        "transfer": round((total - starttransfer) * 1000, 1),
        "total": round(total * 1000, 1),
    }

    order = ["dns", "tcp", "tls", "server", "transfer"]
    slowest = order[0]
    for key in order:
        if result[key] > result[slowest]:
            slowest = key
    result["slowest"] = slowest
    return result

