function analyzeTimings(timings) {
  const keys = ['namelookup', 'connect', 'appconnect', 'starttransfer', 'total'];
  const values = keys.map((key) => (timings ? timings[key] : undefined));

  const valid = values.every((value) => typeof value === 'number' && Number.isFinite(value) && value >= 0);
  if (!valid) throw new Error('invalid timings');
  for (let index = 1; index < values.length; index += 1) {
    if (values[index] < values[index - 1]) throw new Error('invalid timings');
  }

  const round = (value) => Math.round((value + Number.EPSILON) * 10) / 10;
  const [namelookup, connect, appconnect, starttransfer, total] = values;
  const result = {
    dns: round(namelookup * 1000),
    tcp: round((connect - namelookup) * 1000),
    tls: round((appconnect - connect) * 1000),
    server: round((starttransfer - appconnect) * 1000),
    transfer: round((total - starttransfer) * 1000),
    total: round(total * 1000),
  };

  const order = ['dns', 'tcp', 'tls', 'server', 'transfer'];
  let slowest = order[0];
  for (const key of order) {
    if (result[key] > result[slowest]) slowest = key;
  }
  return { ...result, slowest };
}

