exercises.solution:
function runWithLimit(tasks, limit) {
  const size = tasks.length;
  if (size === 0) return Promise.resolve([]);
  const max = Number.isInteger(limit) && limit > 0 ? Math.min(limit, size) : 1;
  const results = new Array(size);
  let next = 0;
  let active = 0;
  let settled = false;

  return new Promise((resolve, reject) => {
    const launch = () => {
      if (settled) return;
      while (active < max && next < size) {
        const index = next;
        next += 1;
        active += 1;
        Promise.resolve()
          .then(() => tasks[index]())
          .then(
            (value) => {
              results[index] = value;
              active -= 1;
              if (next === size && active === 0) resolve(results);
              else launch();
            },
            (error) => {
              if (settled) return;
              settled = true;
              reject(error);
            },
          );
      }
    };
    launch();
  });
}

