import re


def parse_listeners(output):
    entries = []
    for raw in str(output or "").splitlines():
        line = raw.strip()
        if not line:
            continue
        entry = None

        if line.startswith("LISTEN"):
            parts = line.split()
            if len(parts) < 4:
                continue
            match = re.match(r"^(.*):(\d+)$", parts[3])
            if not match:
                continue
            address = match.group(1)
            if address.startswith("[") and address.endswith("]"):
                address = address[1:-1]
            user = re.search(r'users:\(\("([^"]+)",pid=(\d+)', line)
            entry = {
                "address": address,
                "port": int(match.group(2)),
                "pid": int(user.group(2)) if user else None,
                "process": user.group(1) if user else None,
            }
        elif "(LISTEN)" in line:
            parts = line.split()
            if len(parts) < 2 or not parts[1].isdigit():
                continue
            try:
                protocol_index = parts.index("TCP")
            except ValueError:
                try:
                    protocol_index = parts.index("TCP6")
                except ValueError:
                    continue
            if protocol_index + 1 >= len(parts):
                continue
            match = re.match(r"^(.*):(\d+)$", parts[protocol_index + 1])
            if not match:
                continue
            address = match.group(1)
            if address.startswith("[") and address.endswith("]"):
                address = address[1:-1]
            entry = {
                "address": address,
                "port": int(match.group(2)),
                "pid": int(parts[1]),
                "process": parts[0],
            }

        if entry:
            entries.append(entry)

    return sorted(entries, key=lambda item: item["port"])

