exercises.solution:
function parseListeners(output) {
  const entries = [];
  const lines = String(output || '').split(/\r?\n/);

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;
    let entry = null;

    if (line.startsWith('LISTEN')) {
      const parts = line.split(/\s+/);
      const local = parts[3];
      const match = local ? /^(.*):(\d+)$/.exec(local) : null;
      if (!match) continue;
      const address = match[1].replace(/^\[|\]$/g, '');
      const port = Number(match[2]);
      if (!Number.isInteger(port) || port <= 0) continue;
      const user = /users:\(\("([^"]+)",pid=(\d+)/.exec(line);
      entry = {
        address,
        port,
        pid: user ? Number(user[2]) : null,
        process: user ? user[1] : null,
      };
    } else if (line.includes('(LISTEN)')) {
      const parts = line.split(/\s+/);
      const pid = Number(parts[1]);
      if (!Number.isInteger(pid)) continue;
      let protocolIndex = parts.indexOf('TCP');
      if (protocolIndex < 0) protocolIndex = parts.indexOf('TCP6');
      if (protocolIndex < 0) continue;
      const local = parts[protocolIndex + 1];
      const match = local ? /^(.*):(\d+)$/.exec(local) : null;
      if (!match) continue;
      const address = match[1].replace(/^\[|\]$/g, '');
      entry = { address, port: Number(match[2]), pid, process: parts[0] };
    }

    if (entry) entries.push(entry);
  }

  return entries.sort((left, right) => left.port - right.port);
}

