def summarize_explain(plan):
    result = {
        "seqScans": 0,
        "indexScans": 0,
        "maxRowMisestimate": 0.0,
        "totalActualTime": 0.0,
        "warnings": [],
    }

    def visit(node):
        if not node:
            return
        name = str(node.get("node", ""))
        if "Seq Scan" in name:
            result["seqScans"] += 1
        if "Index Scan" in name or "Index Only Scan" in name:
            result["indexScans"] += 1

        rows = node.get("rows")
        actual_rows = node.get("actualRows")
        if (
            isinstance(rows, (int, float))
            and isinstance(actual_rows, (int, float))
            and rows > 0
            and actual_rows > 0
        ):
            ratio = max(actual_rows / rows, rows / actual_rows)
            if ratio > result["maxRowMisestimate"]:
                result["maxRowMisestimate"] = ratio
            if ratio > 10:
                result["warnings"].append(
                    f"{name}: 估计 {rows} 行，实际 {actual_rows} 行，偏差 {ratio:.1f}x"
                )

        time = node.get("actualTime", 0)
        if isinstance(time, (int, float)):
            result["totalActualTime"] += time
        for child in node.get("children") or []:
            visit(child)

    visit(plan)
    result["maxRowMisestimate"] = round(result["maxRowMisestimate"], 2)
    result["totalActualTime"] = round(result["totalActualTime"], 2)
    return result

