function summarizeExplain(plan) {
  const result = { seqScans: 0, indexScans: 0, maxRowMisestimate: 0, totalActualTime: 0, warnings: [] };
  const round = (value) => Math.round((value + Number.EPSILON) * 100) / 100;

  const visit = (node) => {
    if (!node) return;
    const name = String(node.node || '');
    if (name.includes('Seq Scan')) result.seqScans += 1;
    if (name.includes('Index Scan') || name.includes('Index Only Scan')) result.indexScans += 1;

    const rows = Number(node.rows);
    const actualRows = Number(node.actualRows);
    if (Number.isFinite(rows) && Number.isFinite(actualRows) && rows > 0 && actualRows > 0) {
      const ratio = Math.max(actualRows / rows, rows / actualRows);
      if (ratio > result.maxRowMisestimate) result.maxRowMisestimate = ratio;
      if (ratio > 10) {
        result.warnings.push(`${name}: 估计 ${rows} 行，实际 ${actualRows} 行，偏差 ${ratio.toFixed(1)}x`);
      }
    }

    const time = Number(node.actualTime);
    if (Number.isFinite(time)) result.totalActualTime += time;
    (node.children || []).forEach(visit);
  };

  visit(plan);
  result.maxRowMisestimate = round(result.maxRowMisestimate);
  result.totalActualTime = round(result.totalActualTime);
  return result;
}

