function createCache({ ttl = 60_000, negativeTtl = 5_000, max = 500, now = Date.now } = {}) {
  const values = new Map();
  const inflight = new Map();

  function read(key) {
    const entry = values.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= now()) {
      values.delete(key);
      return undefined;
    }
    return entry;
  }

  function write(key, value, lifetime) {
    if (!values.has(key) && values.size >= max) {
      values.delete(values.keys().next().value);
    }
    values.set(key, { value, expiresAt: now() + lifetime });
  }

  async function get(key, loader) {
    const cached = read(key);
    if (cached) return cached.value;
    if (inflight.has(key)) return inflight.get(key);

    const task = (async () => {
      try {
        const value = await loader();
        write(key, value, value == null ? negativeTtl : ttl);
        return value;
      } catch (error) {
        values.delete(key);
        throw error;
      } finally {
        inflight.delete(key);
      }
    })();

    inflight.set(key, task);
    return task;
  }

  function set(key, value, options = {}) {
    const lifetime = typeof options.ttl === 'number'
      ? options.ttl
      : value == null
        ? negativeTtl
        : ttl;
    write(key, value, lifetime);
  }

  function remove(key) {
    values.delete(key);
  }

  return { get, set, delete: remove };
}

