}

function createCircuitBreaker({ failureThreshold = 3, cooldownMs = 1000, now = Date.now } = {}) {
  if (!(failureThreshold >= 1)) throw new RangeError('failureThreshold must be >= 1');
  if (!(cooldownMs >= 0)) throw new RangeError('cooldownMs must be >= 0');

  let state = 'closed';
  let failures = 0;
  let openedAt = 0;
  let probing = false;

  function refresh() {
    if (state === 'open' && now() - openedAt >= cooldownMs) {
      state = 'half-open';
      probing = false;
    }
  }

  async function execute(fn) {
    refresh();
    if (state === 'open') throw new CircuitOpenError();
    if (state === 'half-open') {
      if (probing) throw new CircuitOpenError('probe in progress');
      probing = true;
    }
    try {
      const result = await fn();
      state = 'closed';
      failures = 0;
      probing = false;
      return result;
    } catch (error) {
      if (state === 'half-open') {
        state = 'open';
        openedAt = now();
        probing = false;
      } else {
        failures += 1;
        if (failures >= failureThreshold) {
          state = 'open';
          openedAt = now();
        }
      }
      throw error;
    }
  }

  return {
    execute,
    get state() {
      refresh();
      return state;
    },
  };
}

