  async function execute(fn) {
    refresh();
    if (state === 'open') throw new CircuitOpenError();
    if (state === 'half-open') {
      if (probing) throw new CircuitOpenError('probe in progress');
      probing = true;
    }
    try {
      const result = await fn();
      state = 'closed';
      failures = 0;
      probing = false;
      return result;
    } catch (error) {
      if (state === 'half-open') {
        state = 'open';
        openedAt = now();
        probing = false;
      } else {
        failures += 1;
        if (failures >= failureThreshold) {
          state = 'open';
          openedAt = now();
        }
      }
      throw error;
    }
  }

  return {
    execute,
    get state() {
      refresh();
      return state;
    },
  };
}

