function createShutdown({
  server,
  timeoutMs = 10_000,
  onDrain = async () => {},
  scheduler = { setTimeout, clearTimeout },
} = {}) {
  let state = 'running';
  let pending = null;
  let result = null;
  let timer = null;

  function finalize(payload) {
    result = payload;
    state = 'closed';
    if (timer !== null) {
      scheduler.clearTimeout(timer);
      timer = null;
    }
    return payload;
  }

  function begin() {
    return new Promise((resolve) => {
      state = 'draining';
      timer = scheduler.setTimeout(() => {
        if (state === 'closed') return;
        resolve(finalize({ forced: true, reason: 'TIMEOUT' }));
      }, timeoutMs);

      server.close(async (error) => {
        if (state === 'closed') return;
        if (error) {
          resolve(finalize({ forced: false, error }));
          return;
        }
        try {
          await onDrain();
          resolve(finalize({ forced: false }));
        } catch (drainError) {
          resolve(finalize({ forced: false, error: drainError }));
        }
      });
    });
  }

  function shutdown() {
    if (pending) return pending;
    if (state === 'closed') return Promise.resolve(result);
    pending = begin();
    return pending;
  }

  return {
    shutdown,
    state: () => state,
    isAccepting: () => state === 'running',
  };
}

