def analyze_graph(graph=None, rules=None):
    graph = graph or {}
    rules = rules or []
    names = set(graph)
    for deps in graph.values():
        names.update(deps or [])
    ordered = sorted(names)
    adjacency = {name: [] for name in ordered}
    for name in graph:
        adjacency[name] = sorted(set(graph.get(name) or []))

    color = {name: 0 for name in ordered}
    stack = []
    seen = set()
    cycles = []

    def canonical(path):
        opening = path[:-1]
        best = None
        for index in range(len(opening)):
            key = '>'.join(opening[index:] + opening[:index])
            if best is None or key < best:
                best = key
        return best

    def visit(name):
        color[name] = 1
        stack.append(name)
        for dep in adjacency.get(name, []):
            if dep not in adjacency:
                continue
            if color[dep] == 0:
                visit(dep)
            elif color[dep] == 1:
                start = stack.index(dep)
                path = stack[start:] + [dep]
                key = canonical(path)
                if key not in seen:
                    seen.add(key)
                    cycles.append(path)
        stack.pop()
        color[name] = 2

    for name in ordered:
        if color[name] == 0:
            visit(name)
    cycles.sort(key=lambda path: '>'.join(path))

    violations = []
    for rule in rules:
        source = rule.get('name') or rule.get('from')
        forbidden = rule.get('forbid') or []
        for dep in adjacency.get(source, []):
            if dep in forbidden:
                violations.append({
                    'from': source,
                    'to': dep,
                    'rule': rule.get('id') or source + '->' + dep,
                })
    return {'cycles': cycles, 'violations': violations}

