function createStore() {
  const locks = new Map();
  const data = {};
  let token = 0;
  return {
    data,
    get(key) { return locks.get(key) || null; },
    set(key, record) { locks.set(key, record); },
    delete(key) { locks.delete(key); },
    nextToken() { token += 1; return token; },
