    while (low < high) {
      const mid = (low + high) >> 1;
      if (ring[mid].position < target) low = mid + 1;
      else high = mid;
    }
    if (ring[low].position < target) low = 0;
    return ring[low].node;
  }

  nodes.forEach(addNode);
  return {
    getNode,
    addNode,
