function summarizeBenchmark(samples) {
  if (!Array.isArray(samples) || samples.length === 0) {
    return { count: 0, mean: 0, p50: 0, p95: 0, p99: 0, cv: 0, stable: false };
  }
  const values = samples.map((sample) => sample.ms);
  for (const value of values) {
    if (!Number.isFinite(value) || value < 0) throw new Error('INVALID_SAMPLE');
  }
  const sorted = [...values].sort((a, b) => a - b);
  const n = values.length;
  const mean = values.reduce((sum, value) => sum + value, 0) / n;
  const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / n;
  const cv = mean === 0 ? 0 : Math.sqrt(variance) / mean;
  const percentile = (p) => sorted[Math.max(0, Math.ceil((p / 100) * n) - 1)];
  return {
    count: n,
    mean,
    p50: percentile(50),
    p95: percentile(95),
    p99: percentile(99),
    cv,
    stable: cv <= 0.1,
  };
}

