function createHashMap({ initialCapacity = 8, maxLoad = 0.75 } = {}) {
  let capacity = Math.max(1, initialCapacity | 0);
  let keys = new Array(capacity).fill(undefined);
  let values = new Array(capacity).fill(undefined);
  let state = new Array(capacity).fill(0); // 0 空、1 占用、2 墓碑
  let size = 0;
  let tombstones = 0;

  const hash = (key) => {
