    while (leaf) {
      for (const key of leaf.keys) {
        if (key > hi) return result;
        if (key >= lo) result.push(key);
      }
      leaf = leaf.next;
    }
    return result;
  }

  function keys() {
    const result = [];
    let leaf = root;
    while (!leaf.leaf) leaf = leaf.children[0];
    while (leaf) {
      result.push(...leaf.keys);
      leaf = leaf.next;
    }
    return result;
  }

  return { insert, search, range, height: () => treeHeight, keys };
}

