function createHLL(precision) {
  if (!Number.isInteger(precision) || precision < 4 || precision > 16) {
    throw new Error('INVALID_PRECISION');
  }
  const bucketCount = 2 ** precision;
  const buckets = new Array(bucketCount).fill(0);
  const fmix32 = (h) => {
    h ^= h >>> 16;
    h = Math.imul(h, 0x85ebca6b);
    h ^= h >>> 13;
    h = Math.imul(h, 0xc2b2ae35);
    h ^= h >>> 16;
    return h >>> 0;
  };
  const hash64 = (value) => {
    let h1 = 0x811c9dc5;
    let h2 = 0x9e3779b9;
    for (const ch of String(value)) {
      h1 = Math.imul(h1 ^ ch.charCodeAt(0), 0x01000193) >>> 0;
      h2 = (Math.imul(h2 ^ ch.charCodeAt(0), 0x85ebca6b) + 0x165667b1) >>> 0;
    }
    return [fmix32(h1), fmix32(h2)];
  };
  return {
    add(value) {
      const [h1, h2] = hash64(value);
      const index = h1 >>> (32 - precision);
      const rank = h2 === 0 ? 33 : Math.clz32(h2) + 1;
      if (rank > buckets[index]) buckets[index] = rank;
    },
    estimate() {
      const m = bucketCount;
      let sum = 0;
      let zeros = 0;
      for (const value of buckets) {
        sum += 2 ** (-value);
        if (value === 0) zeros += 1;
      }
      const alpha = m === 16 ? 0.673 : m === 32 ? 0.697 : m === 64 ? 0.709 : 0.7213 / (1 + 1.079 / m);
      let raw = (alpha * m * m) / sum;
      if (raw <= 2.5 * m && zeros > 0) raw = m * Math.log(m / zeros);
      return raw;
    }
  };
}

