function estimateCapacity({ peakQps, readRatio, cacheHitRate, readPerInstance, writePerInstance, targetUtilization }) {
  const reads = peakQps * readRatio;
  const writes = peakQps * (1 - readRatio);
  const originReads = reads * (1 - cacheHitRate);
  const readNodes = Math.ceil(originReads / (readPerInstance * targetUtilization));
  const writeNodes = Math.ceil(writes / (writePerInstance * targetUtilization));
  return {
    originReads,
    readNodes,
    writeNodes,
    totalNodes: Math.max(readNodes, writeNodes) + 1,
  };
}

function createWeightedRoundRobin(servers) {
  const list = servers.map((server) => ({
    name: server.name,
    weight: server.weight,
    healthy: server.healthy !== false,
    current: 0
  }));
  return {
    pick() {
      const candidates = list.filter((server) => server.healthy && server.weight > 0);
      if (candidates.length === 0) return null;
      let total = 0;
      let best = null;
      for (const server of candidates) {
        total += server.weight;
        server.current += server.weight;
        if (best === null || server.current > best.current) best = server;
      }
      best.current -= total;
      return best.name;
    }
  };
}

