function checkFdBudget({ systemLimit, workerProcesses, connectionsPerWorker, filesPerConnection, reserve }) {
  const values = { systemLimit, workerProcesses, connectionsPerWorker, filesPerConnection, reserve };
  for (const [name, value] of Object.entries(values)) {
    if (!Number.isFinite(value) || value <= 0) throw new Error('INVALID_' + name.toUpperCase());
  }
  const required = workerProcesses * connectionsPerWorker * filesPerConnection + reserve;
  return {
    ok: required <= systemLimit,
    required,
    headroom: systemLimit - required
  };
}

