  'clarify', 'estimate', 'api', 'data',
  'architecture', 'bottleneck', 'failure', 'tradeoff',
];

function auditAnswer(answer) {
  const present = new Set(answer.sections || []);
  const missing = REQUIRED_SECTIONS.filter((section) => !present.has(section));
  const score = Math.round(((REQUIRED_SECTIONS.length - missing.length) / REQUIRED_SECTIONS.length) * 100);
  return { complete: missing.length === 0, missing, score };
}

