function detectFlaky(history) {
  return history
    .map(({ name, results }) => {
      let flips = 0;
      for (let i = 1; i < results.length; i += 1) {
        if (results[i] !== results[i - 1]) flips += 1;
      }
      return { name, flips, flaky: flips >= 2 };
    })
    .sort((a, b) => b.flips - a.flips || (a.name < b.name ? -1 : 1));
}

