const POSTMORTEM_REQUIRED = [
  'title', 'severity', 'timeline', 'impact', 'detection',
  'rootCause', 'actions', 'owners', 'verification',
];

function auditPostmortem(doc) {
  const missing = POSTMORTEM_REQUIRED.filter((field) => {
    const value = doc[field];
    if (Array.isArray(value)) return value.length === 0;
    return typeof value !== 'string' || value.trim() === '';
  });
  const vague = (doc.actions || []).filter((action) => /加强意识|以后注意|后续优化/.test(action));
  return { ok: missing.length === 0 && vague.length === 0, missing, vague };
}

