function estimateMonthlyCost({
  requestsPerDay,
  inputTokens,
  outputTokens,
  inputPricePerMillion,
  outputPricePerMillion,
  cacheHitRate = 0,
}) {
  const billableRequests = requestsPerDay * (1 - cacheHitRate);
  const inputCost = (billableRequests * inputTokens / 1e6) * inputPricePerMillion;
  const outputCost = (billableRequests * outputTokens / 1e6) * outputPricePerMillion;
  const daily = inputCost + outputCost;
  return { daily, monthly: daily * 30 };
}

estimateMonthlyCost({
  requestsPerDay: 20000,
  inputTokens: 1800,
  outputTokens: 350,
  inputPricePerMillion: 2,
  outputPricePerMillion: 8,
  cacheHitRate: 0.3,
});
